{"results": [{"id": "FAM:SF-CHT-009", "label": "Study family SF-CHT-009: Superstar suppression by lineup and forced play type", "score": 1.325, "reached_via": ["request matches the question or hypothesis of FAM:SF-CHT-009 (0.75)", "request matches RQC:RQC-108 (0.72); FAM:SF-CHT-009 auto_addresses_question RQC:RQC-108"], "attributes": {"observed_research_question": "Superstar suppression by lineup and forced play type", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "Named star initiators have identifiable lineup and forced-play-type suppressors in the possession graph.", "observed_result": "Jokic vs MIN lineup PPP 0.814, -0.385 (n=59); Curry vs HOU 0.851, -0.358 (n=47); Doncic vs LAC 0.733, -0.396 (n=30); Giannis forced PULL_UP 0.848, -0.540 vs preferred DRIVE (largest gap).", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "No placebo or matching; later sequence work treated similar star-chain gaps as artifacts.", "observed_sample_and_power": "n>=30 for lineup cells cited", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_method": "Jokic/Curry/Doncic/Giannis; min-15 gate on 8 play types; opposing DEFENSE_LINEUP ~84% coverage; 272-row CSV."}, "relationships": [{"rel": "auto_has_risk", "node": "RISK:PLACEBO_DEPENDENCE"}]}, {"id": "FAM:SF17", "label": "Study family SF17: Wiring confirmatory: persistence (P1a) and irreducibility to play-type rates (P1b)", "score": 1.061, "reached_via": ["request matches the question or hypothesis of FAM:SF17 (0.75)", "request matches RQC:RQC-011 (0.71); FAM:SF17 auto_addresses_question RQC:RQC-011"], "attributes": {"observed_research_question": "Wiring confirmatory: persistence (P1a) and irreducibility to play-type rates (P1b)", "auto_outcome_status": "supported", "observed_hypothesis": "Team offensive association structure is more similar to itself across split halves than to other teams, even after residualizing play-type rates.", "observed_result": ["[APPS-080] Gate: C1 8/8 p<0.05; C2 S=0.319 perm_p=0.0002; C3 R2=0.080 PASS. Full: frobenius P1a S=0.352 p=0.0000 CI[0.327,0.378]; P1b S=0.353 CI[0.329,0.379]; cosine P1a 0.155 / P1b 0.144. residual_R2=0.043. D_obs mean=3 [cut; read_family for the full text]", "[CHT-049] Residual R^2=0.043. Frobenius P1a S=0.352 p=0.0000 CI [0.327, 0.378]; P1b S=0.353 [0.329, 0.379]. Cosine P1a S=0.155 [0.132, 0.179]; P1b S=0.144 [0.123, 0.170]. All p<0.01."], "auto_failure_mechanism": "D_positive (no failure: positive result)", "observed_failure_evidence": "[CHT-049] NOT_RECORDED"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF-PAP-001"}]}, {"id": "FAM:SF-APPA-050", "label": "Study family SF-APPA-050: Superstar sequential suppression: opponent play before the star", "score": 0.861, "reached_via": ["FAM:SF-APPM-022 auto_related_family (repeated_by_later_family) FAM:SF-APPA-050", "FAM:SF-APPM-022 auto_related_family (repeat_of_earlier_family) FAM:SF-APPA-050"], "attributes": {"observed_research_question": "Superstar sequential suppression: opponent play before the star", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "A specific opponent play type on the preceding possession suppresses each star's next-possession PPP relative to that star's baseline.", "observed_result": "PUTBACK is top suppressor for 6+ stars (e.g. D. Mitchell 1.178 to 0.884, d=-0.294, n_after=95; B. Beal d=-0.345 n=32; C. Holmgren d=-0.222 n=52). Other tops: TRANSITION (A. Davis -0.058), POST_UP (N. Jokic -0.075), PULL_ [cut; read_family for the full text]", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "No multiplicity correction; n_after is 32-95 for several PUTBACK cells vs thousands of baseline possessions.", "observed_sample_and_power": "30 stars; min n_after=30", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED"}, "relationships": [{"rel": "auto_has_risk", "node": "RISK:DRIFT_NONSTATIONARITY"}]}, {"id": "FAM:SF-APPM-022", "label": "Study family SF-APPM-022: Superstar suppression profiles (incl. Q5c sequential triggering)", "score": 0.861, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPM-022 (0.74)", "request matches DS:NBA_play_by_play_possessions_and_reconstructed_lineups (0.72); FAM:SF-APPM-022 auto_uses_dataset DS:NBA_play_by_play_possessions_and_reconstructed_lineups"], "attributes": {"observed_research_question": "Superstar suppression profiles (incl. Q5c sequential triggering)", "auto_outcome_status": "inconclusive", "observed_hypothesis": "Specific opposing lineups, defenders, play types and preceding opponent play types suppress star efficiency.", "observed_result": "Q5c verdict 'rank-1 suppressor varies meaningfully across players'; e.g. Jokic after opp POST_UP 1.1271 (-0.0675, SE +/-0.0500, n=480); Curry forced POST_UP -0.209.", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "Rank-1 deltas mostly within 1-2 SE with no multiple-comparison control; OTHER artifact flagged in doc.", "observed_sample_and_power": "SE per cell reported", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "inconclusive", "observed_failure_type": "E_unclear", "observed_notes": "NOT_RECORDED", "auto_confidence": "medium (0.65)"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF-APPA-050"}]}, {"id": "FAM:SF-CHT-039", "label": "Study family SF-CHT-039: Series-level AVOID share vs winning (talent confound)", "score": 0.734, "reached_via": ["request matches the question or hypothesis of FAM:SF-CHT-039 (0.73)"], "attributes": {"observed_research_question": "Series-level AVOID share vs winning (talent confound)", "auto_outcome_status": "untestable", "observed_hypothesis": "Higher AVOID share predicts losing, independent of team quality.", "observed_result": "Game-level rho=-0.19 p=0.008 (inflated n, team-quality confound). Series-level rho=-0.26 p=0.07 (n=50, underpowered; ~80 series needed for p<0.05). Low AVOID-share bin 52.6% vs 25-50% bin 37.0%.", "auto_failure_mechanism": "A_unanswerable (question not answerable with the data or design)", "observed_failure_evidence": "Series n=50 p=0.07; still confounded by team quality (OKC disciplined and good).", "observed_sample_and_power": "n=50 series; stated need ~80 for p<0.05", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "inconclusive"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:confounding"}, {"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:CONFOUNDING"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}]}, {"id": "FAM:SF18", "label": "Study family SF18: Fragility confirmatory: F1a usage decoupling and F1b split-half stability of residual influence", "score": 0.684, "reached_via": ["FAM:SF17 auto_related_family (record_link_related_to) FAM:SF18", "request matches RQC:RQC-011 (0.71); FAM:SF18 auto_addresses_question RQC:RQC-011"], "attributes": {"observed_research_question": "Fragility confirmatory: F1a usage decoupling and F1b split-half stability of residual influence", "auto_outcome_status": "supported", "observed_hypothesis": "Structural influence is not reducible to usage and the usage-residual is a reproducible player property.", "observed_result": ["[APPA-039] F1a cosine R2=0.094, residual-share=0.906, CI [0.768, 0.962] PASS; Frobenius R2=0.073 share=0.927 CI [0.828, 0.965]. F1b pooled-residual rho=+0.685 p=0.0000 CI [+0.649, +0.721]; usage-partial rho=+0.557 p=0.00 [cut; read_family for the full text]", "[APPS-083] F1a cosine R2=0.099 share=0.901 CI[0.778,0.954]; frobenius R2=0.084 share=0.916. F1b pooled rho=+0.670 p=0.0000 CI[+0.636,+0.705]; partial rho=+0.560 CI[+0.496,+0.616]. F1a=CONFIRMED F1b=CONFIRMED."], "auto_failure_mechanism": "D_positive (no failure: positive result)"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:low_measurement_reliability"}, {"rel": "auto_has_risk", "node": "RISK:MEASURE_RELIABILITY"}]}, {"id": "FAM:SF20", "label": "Study family SF20: Absence validation (structure moves under real absence; simulation tracks it)", "score": 0.684, "reached_via": ["FAM:SF17 auto_related_family (record_link_related_to) FAM:SF20", "request matches RQC:RQC-011 (0.71); FAM:SF20 auto_addresses_question RQC:RQC-011"], "attributes": {"observed_research_question": "Absence validation (structure moves under real absence; simulation tracks it)", "auto_outcome_status": "untestable", "observed_hypothesis": "Real player absences move the association structure (V1) and the LOO simulation predicts the magnitude (V2).", "observed_result": ["[APPA-006] Gate G2 21/23 (91%) above null median; V1(a) 16/23 above own-null p95, binomial p=2.67e-16; V1(b) mean(D_real - median_null)=+0.142, CI [+0.103, +0.187].", "[APPA-007] Gate G3 Spearman +0.099. V2a Spearman +0.288, p=0.077, CI [-0.244, +0.667] FAIL; V2b partial +0.253, p=0.115, CI [-0.262, +0.615] FAIL. Diagnostics: H_code ruled out (rho=0.933); dropping 2 absorption cases rh [cut; read_family for the full text]", "[PAP-023] V1(a) 16/23 above p95 binomial p=2.67e-16; V1(b) +0.142 CI[+0.103,+0.187] CONFIRMED; V2a rho=+0.288 p=0.077 CI[-0.244,+0.667]; V2b rho=+0.253 p=0.115 NOT"]}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:small_sample"}]}, {"id": "FAM:SF-APPA-066", "label": "Study family SF-APPA-066: TOV_FORCE matchup decomposition on four playoff games", "score": 0.569, "reached_via": ["request matches RQC:RQC-066 (0.72); FAM:SF-APPA-066 auto_addresses_question RQC:RQC-066", "request matches DS:NBA_play_by_play_possessions_and_reconstructed_lineups (0.72); FAM:SF-APPA-066 auto_uses_dataset DS:NBA_play_by_play_possessions_and_reconstructed_lineups"], "attributes": {"observed_research_question": "TOV_FORCE matchup decomposition on four playoff games", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "TOV_FORCE as a top-3 lever can be decomposed into defender x initiator x PT channels with positive matchup lift.", "observed_result": "Team-PT lifts are small (ORL vs DET PNR +1.2pp; POR vs SAS all PT lifts negative, e.g. PNR -4.1pp) while player-channel lifts are large on small n (Banchero on Huerter SPOT_UP +8.4pp, n_def=17 / n_off=54; Dort on Coffey  [cut; read_family for the full text]", "auto_failure_mechanism": "A_unanswerable (question not answerable with the data or design)", "observed_failure_evidence": "Player-channel n often 15-28 defensive possessions; primary_defender attribution includes helper steals; no holdout or game-outcome check.", "observed_sample_and_power": "4 games; cell n often 15-54"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:insufficient_exposure"}, {"rel": "auto_has_risk", "node": "RISK:EXPOSURE_SPARSITY"}]}, {"id": "FAM:SF-APPS-074", "label": "Study family SF-APPS-074: Gravity persistence: elite creator -> teammate PPP at lags 1-3", "score": 0.567, "reached_via": ["request matches RQC:RQC-102 (0.71); FAM:SF-APPS-074 auto_addresses_question RQC:RQC-102", "request matches DS:NBA_play_by_play_possessions_and_reconstructed_lineups (0.72); FAM:SF-APPS-074 auto_uses_dataset DS:NBA_play_by_play_possessions_and_reconstructed_lineups"], "attributes": {"observed_research_question": "Gravity persistence: elite creator -> teammate PPP at lags 1-3", "auto_outcome_status": "rejected", "observed_hypothesis": "After an elite creator's signature action, teammates score more on the team's next k possessions with the same lineup on the floor.", "observed_result": "All 8 creators horizon=0. Jokic lag-1 ATT=+0.0282 CI[-0.043,+0.099] p=0.3779. CLEAN NULL on teammate PPP. Secondary: Antetokounmpo +0.075 distinct initiators over next 3 poss (perm p=0.0002, BH 0.003) ? structure not eff [cut; read_family for the full text]", "auto_failure_mechanism": "B_powered_null (adequately powered null result)", "observed_failure_evidence": "No elite creator produces a positive lineup-matched teammate-PPP lift at any lag.", "observed_sample_and_power": "Jokic lag-1 n=1880; Giannis n=1804; Doncic n=325", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "null"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF30"}]}, {"id": "FAM:SF-APPS-059", "label": "Study family SF-APPS-059: Sequence-memory horizon test (per-lag vs aggregated window)", "score": 0.494, "reached_via": ["FAM:SF17 auto_related_family (record_link_related_to) FAM:SF-APPS-059", "request matches DS:NBA_play_by_play_possessions_and_reconstructed_lineups (0.72); FAM:SF-APPS-059 auto_uses_dataset DS:NBA_play_by_play_possessions_and_reconstructed_lineups"], "attributes": {"observed_research_question": "Sequence-memory horizon test (per-lag vs aggregated window)", "auto_outcome_status": "supported", "observed_hypothesis": "Increasing prior-possession history changes the opponent's next-possession outcome after controlling for game state.", "observed_result": "Per-lag GBT AUC N=0 0.5621 -> N=1 0.5863 (d+0.0242) -> N=3 0.5907 -> N=8 0.5911. R2 0.0051 -> 0.0133. Aggregated window declines after N=1 (AUC 0.5868 -> 0.5687 at N=8). Effective horizon ~2-3 possessions.", "auto_failure_mechanism": "D_positive (no failure: positive result)", "observed_failure_evidence": "Short-memory horizon is stable OOS; almost all gain is lag-1, plateau by lag 4. Absolute AUC still only ~0.591.", "observed_sample_and_power": "n=1,024,980 possessions; time-split test 2025-26", "observed_verdict": "supported"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}, {"rel": "auto_related_family", "node": "FAM:SF-APPS-070"}, {"rel": "auto_related_family", "node": "FAM:SF17"}]}], "n_results": 10}

